import XCTest
import PipelineKit
@testable import PipelineKitCache

final class CacheIdentityContractTests: XCTestCase {
    func testCacheIdentityMatrix() async throws {
        let routes: [(String, any Middleware)] = [
            ("Cached", CachedMiddleware(wrapping: PassThrough(), cache: InMemoryMiddlewareCache())),
            ("Conditional", ConditionalCachedMiddleware(wrapping: PassThrough(), cache: InMemoryMiddlewareCache(), shouldCache: { _, _ in true })),
            ("Simple", SimpleCachingMiddleware(ttl: 60)),
            ("Caching", CachingMiddleware(cache: InMemoryCache()))
        ]
        for (name, middleware) in routes {
            for principal in ["alice", "bob"] {
                for argument in ["one", "two"] {
                    let context = CommandContext(metadata: DefaultCommandMetadata(userID: principal))
                    let result = try await middleware.execute(Query(argument: argument), context: context) { command, context in
                        "\(command.argument)/\(context.commandMetadata.userID!)"
                    }
                    XCTAssertEqual(result, "\(argument)/\(principal)", name)
                }
            }
        }
    }

    func testEqualHashValuesDoNotShareResults() async throws {
        let first = Query(argument: "one")
        let second = Query(argument: "two")
        XCTAssertNotEqual(first, second)
        XCTAssertEqual(first.hashValue, second.hashValue)
        let routes: [any Middleware] = [
            SimpleCachingMiddleware(ttl: 60, useHashableKeys: true),
            CachingMiddleware(cache: InMemoryCache(), commandType: Query.self)
        ]
        for middleware in routes {
            for command in [first, second] {
                let result = try await middleware.execute(command, context: CommandContext()) { command, _ in command.argument }
                XCTAssertEqual(result, command.argument, "\(type(of: middleware))")
            }
        }
    }

    func testExplicitKeysStillNamespaceDifferentCommandTypes() async throws {
        let middleware = CachedMiddleware(wrapping: PassThrough(), cache: InMemoryMiddlewareCache(), keyGenerator: SharedKey())
        let first = try await middleware.execute(Left.Query(), context: CommandContext()) { _, _ in "left" }
        let second = try await middleware.execute(Right.Query(), context: CommandContext()) { _, _ in "right" }
        XCTAssertEqual(first, "left")
        XCTAssertEqual(second, "right")
    }
}

private struct Query: Command, Hashable {
    typealias Result = String
    let argument: String
    func hash(into hasher: inout Hasher) { hasher.combine(0) }
}
private enum Left { struct Query: Command { typealias Result = String } }
private enum Right { struct Query: Command { typealias Result = String } }
private struct SharedKey: CacheKeyGenerator {
    func generateKey<T: Command>(for command: T, context: CommandContext, middleware: String) async -> String { "" }
}
private struct PassThrough: Middleware {
    let priority: ExecutionPriority = .preProcessing
    func execute<T: Command>(_ command: T, context: CommandContext, next: @escaping MiddlewareNext<T>) async throws -> T.Result {
        try await next(command, context)
    }
}
